import 'package:flutter_test/flutter_test.dart';
import 'package:amina/core/data/meal_food_catalog.dart';
import 'package:amina/features/journal/widgets/food_pictogram_painter_batch29.dart';
void main(){const ids=<String>['jordanian_mansaf','jordanian_rashouf','jordanian_makmoura'];test('B29 appends three Jordan concepts after certified B28 baseline',(){expect(mealFoodCatalog.length,389);expect(mealFoodCatalog.skip(386).map((e)=>e.id).toList(),ids);expect(mealFoodCatalog.map((e)=>e.id).toSet().length,389);});test('B29 labels search categories and native pictograms are complete',(){for(final id in ids){final item=mealFoodById(id);expect(item,isNotNull);expect(item!.fr,isNotEmpty);expect(item.en,isNotEmpty);expect(item.ar,isNotEmpty);expect(hasCodeFoodPictogramBatch29(id),isTrue);expect(searchMealFoods(item.fr).map((e)=>e.id),contains(id));}expect(mealFoodById('jordanian_mansaf')!.category,MealFoodCategory.meatPoultry);expect(mealFoodById('jordanian_rashouf')!.category,MealFoodCategory.soup);expect(mealFoodById('jordanian_makmoura')!.category,MealFoodCategory.meatPoultry);});}
